window.receiveProjectSource({"path": "src/db/ingest_ledger/models/delivery_units.py", "lines": ["\"\"\"ORM model for ``ingest_ledger.delivery_units`` (generated from ERD IngestLedger-version-1.06).\"\"\"", "", "from datetime import datetime", "from uuid import UUID as UUIDType", "", "from sqlalchemy import (", "    BigInteger,", "    CheckConstraint,", "    Computed,", "    DateTime,", "    ForeignKeyConstraint,", "    Index,", "    Integer,", "    PrimaryKeyConstraint,", "    Text,", "    UniqueConstraint,", "    text,", ")", "from sqlalchemy.dialects.postgresql import UUID", "from sqlalchemy.orm import Mapped, mapped_column", "", "from db.ingest_ledger.base import SCHEMA, IngestLedgerBase", "from db.ingest_ledger.enums import (", "    BORN_SUPERSEDED_POSTURES,", "    DELETE_SEMANTIC_MODES,", "    DELIVERY_UNIT_STATES,", "    DOWNSTREAM_ROUTES,", "    INGESTION_METHODS,", "    LATENCY_CLASSES,", "    LIFECYCLE_OPS,", "    MANIFEST_REPRESENTATIONS,", "    ORDERING_MODE_TYPES,", "    PAYLOAD_ARRIVAL_MODES,", "    PAYLOAD_DISPOSITIONS,", "    QUARANTINE_REASON_CODES,", "    SCOPE_KINDS,", "    UNIT_NATURAL_KEY_KINDS,", "    VERSION_ORDER_ENCODINGS,", ")", "", "", "class DeliveryUnit(IngestLedgerBase):", "    \"\"\"One row per delivery unit, uniformly \u2014 a single submission is a unit of one; a file, page, or batch is one row whose interior records live in Sub_Unit_Manifests.\"\"\"", "", "    __tablename__ = \"delivery_units\"", "    __table_args__ = (", "        PrimaryKeyConstraint(\"id\", name=\"delivery_units_pkey\"),", "        UniqueConstraint(\"id\", \"scope_key\", name=\"delivery_units_id_scope_key_key\"),", "        UniqueConstraint(\"id\", \"client_id\", name=\"delivery_units_id_client_id_key\"),", "        UniqueConstraint(", "            \"id\", \"dataset_id\", \"client_id\", name=\"delivery_units_id_dataset_id_client_id_key\"", "        ),", "        ForeignKeyConstraint(", "            [\"source_system_id\", \"client_id\"],", "            [\"ingest_ledger.source_systems.id\", \"ingest_ledger.source_systems.client_id\"],", "            name=\"delivery_units_source_system_id_client_id_fkey\",", "        ),", "        ForeignKeyConstraint(", "            [\"duplicate_of_delivery_unit_id\", \"client_id\"],", "            [\"ingest_ledger.delivery_units.id\", \"ingest_ledger.delivery_units.client_id\"],", "            name=\"delivery_units_duplicate_of_delivery_unit_id_client_id_fkey\",", "        ),", "        CheckConstraint(", "            \"(state IN ('QUARANTINED', 'EXPIRED') AND quarantine_reason_code IS NOT NULL)\\nOR\\n(state NOT IN ('QUARANTINED', 'EXPIRED') AND quarantine_reason_code IS NULL)\",", "            name=\"ck_delivery_units_quarantine_reason\",", "        ),", "        CheckConstraint(", "            \"(quarantine_reason_code IS DISTINCT FROM 'INTENT_EXPIRED'\\n OR (payload_arrival_mode = 'UPLOAD_INTENT' AND landed_at IS NULL))\\nAND\\n(quarantine_reason_code IS DISTINCT FROM 'LANDING_ABANDONED'\\n OR (payload_arrival_mode = 'REQUEST_BYTES' AND landed_at IS NULL))\",", "            name=\"ck_delivery_units_unlanded_terminal_reason\",", "        ),", "        CheckConstraint(", "            \"(evidence_bucket IS NULL AND evidence_key IS NULL AND evidence_object_version_id IS NULL AND evidence_content_hash IS NULL AND evidence_size_bytes IS NULL)\\nOR\\n(evidence_bucket IS NOT NULL AND evidence_key IS NOT NULL AND evidence_object_version_id IS NOT NULL AND evidence_content_hash IS NOT NULL AND evidence_size_bytes IS NOT NULL)\",", "            name=\"ck_delivery_units_evidence_reference\",", "        ),", "        CheckConstraint(", "            \"state IN ('RECEIVED', 'BLOCKED', 'PENDING_OPERATION_RESOLUTION',\\n          'LANDED', 'QUARANTINED', 'EXPIRED', 'ABSORBED_DUPLICATE')\\nOR payload_disposition IN ('EXTERNAL_REFERENCE', 'RECEIPT_ONLY')\\nOR evidence_content_hash IS NOT NULL\",", "            name=\"ck_delivery_units_accepted_has_evidence\",", "        ),", "        CheckConstraint(", "            \"(state = 'ABSORBED_DUPLICATE'\\n AND manifest_representation IS NULL\\n AND manifest_watermark_ordinal IS NULL)\\nOR (state <> 'ABSORBED_DUPLICATE'\\n    AND (state IN ('RECEIVED', 'BLOCKED',\\n                   'PENDING_OPERATION_RESOLUTION', 'LANDED',\\n                   'ACCEPTED', 'QUARANTINED', 'EXPIRED')\\n         OR (manifest_representation IS NOT NULL\\n             AND ((manifest_representation = 'WATERMARK'\\n                   AND manifest_watermark_ordinal IS NOT NULL)\\n                  OR (manifest_representation = 'EXPLICIT'\\n                      AND manifest_watermark_ordinal IS NULL)))))\",", "            name=\"ck_delivery_units_manifest_plan\",", "        ),", "        CheckConstraint(", "            \"intake_authorization_version >= 1\",", "            name=\"ck_delivery_units_authorization_version\",", "        ),", "        CheckConstraint(", "            \"(quarantine_bucket IS NULL AND quarantine_key IS NULL)\\nOR\\n(quarantine_bucket IS NOT NULL AND quarantine_key IS NOT NULL)\",", "            name=\"ck_delivery_units_quarantine_pair\",", "        ),", "        CheckConstraint(", "            \"payload_arrival_mode = 'NO_POLARIS_BYTES'\\nOR landed_at IS NULL\\nOR (quarantine_bucket IS NOT NULL\\n    AND quarantine_key IS NOT NULL\\n    AND quarantine_object_version_id IS NOT NULL\\n    AND quarantine_content_hash IS NOT NULL\\n    AND quarantine_size_bytes IS NOT NULL)\",", "            name=\"ck_delivery_units_quarantine_landed\",", "        ),", "        CheckConstraint(", "            \"quarantine_content_hash IS NULL\\nOR declared_content_hash IS NULL\\nOR declared_content_hash = quarantine_content_hash\",", "            name=\"ck_delivery_units_declared_hash_honoured\",", "        ),", "        CheckConstraint(", "            \"intent_expires_at IS NULL OR intent_expires_at > received_at\",", "            name=\"ck_delivery_units_intent_expiry\",", "        ),", "        CheckConstraint(", "            \"(payload_disposition IN ('DURABLE', 'TRANSIENT') AND external_reference_uri IS NULL)\\nOR\\n(payload_disposition = 'EXTERNAL_REFERENCE' AND external_reference_uri IS NOT NULL AND evidence_bucket IS NULL AND evidence_key IS NULL AND evidence_object_version_id IS NULL AND evidence_content_hash IS NULL AND evidence_size_bytes IS NULL AND quarantine_key IS NULL)\\nOR\\n(payload_disposition = 'RECEIPT_ONLY' AND external_reference_uri IS NULL AND evidence_bucket IS NULL AND evidence_key IS NULL AND evidence_object_version_id IS NULL AND evidence_content_hash IS NULL AND evidence_size_bytes IS NULL AND quarantine_key IS NULL)\",", "            name=\"ck_delivery_units_disposition_shape\",", "        ),", "        CheckConstraint(", "            \"(ordering_mode <> 'OBSERVATION_ORDERED' OR version_order_encoding = 'ASSIGNED_ORDINAL')\\nAND\\n(ordering_mode <> 'SOURCE_ORDERED' OR version_order_encoding <> 'ASSIGNED_ORDINAL')\",", "            name=\"ck_delivery_units_observation_encoding\",", "        ),", "        CheckConstraint(", "            \"version_order_encoding_version >= 1\",", "            name=\"ck_delivery_units_encoding_version\",", "        ),", "        CheckConstraint(", "            \"(unit_natural_key_kind = 'SOURCE_VERSIONED' AND ordering_mode = 'SOURCE_ORDERED')\\nOR\\n(unit_natural_key_kind IN ('SENDER_DEDUP_KEY', 'MINTED') AND ordering_mode = 'OBSERVATION_ORDERED')\",", "            name=\"ck_delivery_units_natural_key_ordering\",", "        ),", "        CheckConstraint(", "            \"scope_kind IS NULL OR (scope_kind = 'OPERATION' AND operation_id IS NOT NULL) OR (scope_kind = 'STANDING' AND operation_id IS NULL)\",", "            name=\"ck_delivery_units_scope\",", "        ),", "        CheckConstraint(", "            \"state = 'ABSORBED_DUPLICATE'\\nOR (external_namespace IS NULL\\n    AND scope_kind IS NOT NULL AND scope_key IS NOT NULL)\\nOR (external_namespace IS NOT NULL\\n    AND scope_kind IS NOT NULL AND scope_key IS NOT NULL\\n    AND scope_bound_at IS NOT NULL\\n    AND state NOT IN ('RECEIVED', 'BLOCKED',\\n                      'PENDING_OPERATION_RESOLUTION'))\\nOR (external_namespace IS NOT NULL\\n    AND scope_kind IS NULL AND operation_id IS NULL\\n    AND scope_key IS NULL AND scope_bound_at IS NULL\\n    AND state IN ('RECEIVED', 'BLOCKED',\\n                  'PENDING_OPERATION_RESOLUTION',\\n                  'QUARANTINED', 'EXPIRED'))\",", "            name=\"ck_delivery_units_scope_presence\",", "        ),", "        CheckConstraint(", "            \"(external_namespace IS NULL AND external_operation_key IS NULL) OR (external_namespace IS NOT NULL AND external_operation_key IS NOT NULL AND btrim(external_namespace) <> '' AND btrim(external_operation_key) <> '')\",", "            name=\"ck_delivery_units_external_reference_pairing\",", "        ),", "        CheckConstraint(", "            \"(duplicate_of_delivery_unit_id IS NULL\\n AND state <> 'ABSORBED_DUPLICATE')\\nOR (duplicate_of_delivery_unit_id IS NOT NULL\\n    AND state = 'ABSORBED_DUPLICATE'\\n    AND scope_kind IS NULL\\n    AND scope_key IS NULL\\n    AND operation_id IS NULL\\n    AND scope_bound_at IS NULL\\n    AND terminal_at IS NOT NULL)\",", "            name=\"ck_delivery_units_absorbed_duplicate\",", "        ),", "        CheckConstraint(", "            \"(scope_bound_at IS NULL) OR (scope_key IS NOT NULL AND scope_kind = 'OPERATION' AND operation_id IS NOT NULL)\",", "            name=\"ck_delivery_units_scope_binding\",", "        ),", "        CheckConstraint(", "            \"(payload_arrival_mode = 'NO_POLARIS_BYTES' AND payload_disposition IN ('EXTERNAL_REFERENCE', 'RECEIPT_ONLY'))\\nOR\\n(payload_arrival_mode IN ('REQUEST_BYTES', 'UPLOAD_INTENT') AND payload_disposition IN ('DURABLE', 'TRANSIENT'))\",", "            name=\"ck_delivery_units_arrival_mode_disposition\",", "        ),", "        CheckConstraint(", "            \"(quarantine_size_bytes IS NULL OR quarantine_size_bytes > 0) AND (evidence_size_bytes IS NULL OR evidence_size_bytes > 0) AND (declared_size_bytes IS NULL OR declared_size_bytes > 0)\",", "            name=\"ck_delivery_units_sizes_positive\",", "        ),", "        CheckConstraint(", "            \"payload_arrival_mode <> 'NO_POLARIS_BYTES'\\nOR external_namespace IS NULL\\nOR state <> 'RECEIVED'\",", "            name=\"ck_delivery_units_prescope_landing\",", "        ),", "        CheckConstraint(", "            \"(payload_arrival_mode = 'UPLOAD_INTENT' AND intent_expires_at IS NOT NULL)\\nOR\\n(payload_arrival_mode = 'REQUEST_BYTES' AND intent_expires_at IS NULL)\\nOR\\n(payload_arrival_mode = 'NO_POLARIS_BYTES' AND intent_expires_at IS NULL AND quarantine_key IS NULL AND quarantine_bucket IS NULL AND quarantine_object_version_id IS NULL AND quarantine_content_hash IS NULL AND quarantine_size_bytes IS NULL AND evidence_bucket IS NULL AND evidence_key IS NULL AND evidence_object_version_id IS NULL AND evidence_content_hash IS NULL AND evidence_size_bytes IS NULL)\",", "            name=\"ck_delivery_units_arrival_mode_shape\",", "        ),", "        CheckConstraint(", "            \"(payload_arrival_mode = 'NO_POLARIS_BYTES' AND landed_at IS NULL)\\nOR (payload_arrival_mode IN ('REQUEST_BYTES', 'UPLOAD_INTENT')\\n    AND (state IN ('RECEIVED', 'BLOCKED', 'QUARANTINED',\\n                   'EXPIRED', 'ABSORBED_DUPLICATE')\\n         OR landed_at IS NOT NULL))\",", "            name=\"ck_delivery_units_landed_clock\",", "        ),", "        CheckConstraint(", "            \"state NOT IN ('RECEIVED', 'BLOCKED', 'LANDED',\\n              'PENDING_OPERATION_RESOLUTION', 'ABSORBED_DUPLICATE')\\nOR evidence_key IS NULL\",", "            name=\"ck_delivery_units_evidence_not_before_acceptance\",", "        ),", "        CheckConstraint(", "            \"source_dataset_binding_version >= 1\",", "            name=\"ck_delivery_units_dataset_binding_version\",", "        ),", "        CheckConstraint(", "            \"dataset_catalog_version >= 1\",", "            name=\"ck_delivery_units_dataset_catalog_version\",", "        ),", "        Index(", "            \"uq_delivery_units_natural_key\",", "            \"scope_key\",", "            \"source_system_id\",", "            \"unit_natural_key\",", "            unique=True,", "            postgresql_where=text(\"scope_key IS NOT NULL\"),", "        ),", "        Index(\"ix_delivery_units_state_sweep\", \"state\", \"received_at\"),", "        Index(", "            \"ix_delivery_units_batch\",", "            \"ingest_batch_id\",", "            postgresql_where=text(\"ingest_batch_id IS NOT NULL\"),", "        ),", "        Index(\"ix_delivery_units_source_recent\", \"source_system_id\", \"received_at\"),", "        Index(", "            \"ix_delivery_units_evidence_object\",", "            \"evidence_bucket\",", "            \"evidence_key\",", "            \"evidence_object_version_id\",", "            postgresql_where=text(\"evidence_object_version_id IS NOT NULL\"),", "        ),", "        Index(", "            \"ix_delivery_units_quarantine_object\",", "            \"quarantine_bucket\",", "            \"quarantine_key\",", "            \"quarantine_object_version_id\",", "            postgresql_where=text(\"quarantine_key IS NOT NULL\"),", "        ),", "        Index(", "            \"uq_delivery_units_pre_scope_identity\",", "            \"client_id\",", "            \"source_system_id\",", "            \"external_namespace\",", "            \"external_operation_key\",", "            \"unit_natural_key\",", "            unique=True,", "            postgresql_where=text(\"external_namespace IS NOT NULL\"),", "        ),", "        {", "            \"schema\": SCHEMA,", "            \"comment\": (", "                \"One row per delivery unit, uniformly \u2014 a single submission is a unit \"", "                \"of one; a file, page, or batch is one row whose interior records live \"", "                \"in Sub_Unit_Manifests. Rows scale with item count, never bytes.\"", "            ),", "        },", "    )", "", "    id: Mapped[UUIDType] = mapped_column(", "        UUID(as_uuid=True),", "        primary_key=True,", "        nullable=False,", "        comment=\"The delivery_unit_id. Quarantine landing keys derive from this.\",", "    )", "", "    client_id: Mapped[int] = mapped_column(", "        Integer(),", "        nullable=False,", "        comment=(", "            \"From authenticated intake, never payload. Non-null after auth.\\n\\nType \"", "            \"matches ua.clients.id in the Accelerate database. Deliberately \"", "            \"FK-less: this cluster is physically separate and no transaction spans \"", "            \"the two databases.\"", "        ),", "    )", "", "    source_system_id: Mapped[UUIDType] = mapped_column(", "        UUID(as_uuid=True),", "        nullable=False,", "        comment=(", "            \"With client_id, the shard key prefix. Write-once. The duplicate-absorption \"", "            \"check matches a loser against its original on client_id, source_system_id, \"", "            \"unit_natural_key and unit_natural_key_kind, and it runs only at the moment \"", "            \"of absorption; if this column could move afterwards, an absorbed row would \"", "            \"be left pointing at a delivery from a different source system with nothing \"", "            \"to detect it.\"", "        ),", "    )", "", "    scope_kind: Mapped[str | None] = mapped_column(", "        SCOPE_KINDS,", "        nullable=True,", "        comment=(", "            \"The concrete data scope this receipt was admitted into, resolved at \"", "            \"intake from the versioned control policy rather than declared by the \"", "            \"sender. Every scope in the ledger originates here: lineages, claims, \"", "            \"manifests, verdicts, intents and receipts all inherit the kind \"", "            \"recorded on the delivery that created them. Write-once.\"", "        ),", "    )", "", "    operation_id: Mapped[UUIDType | None] = mapped_column(", "        UUID(as_uuid=True),", "        nullable=True,", "        comment=(", "            \"The operation this delivery is confined to. Non-null exactly when \"", "            \"scope_kind is OPERATION and null when it is STANDING. Null alongside \"", "            \"scope_kind while the delivery awaits external-operation resolution and\"", "            \" on a terminal outcome that never resolved. Resolved at intake from \"", "            \"the versioned control policy, which is where a source system's default\"", "            \" operation lives; a source-system registration spans operations and \"", "            \"carries no scope of its own. Deliberately FK-less: operations are \"", "            \"defined in the Accelerate database on a physically separate cluster \"", "            \"and no transaction spans the two. Write-once.\"", "        ),", "    )", "", "    external_namespace: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"The namespace the source declared its operation reference within, \"", "            \"recorded only where the reference required resolution. Non-null \"", "            \"exactly while the unit is pending resolution or has terminated \"", "            \"unresolved, and retained after a successful bind so the reference that\"", "            \" produced the scope stays traceable. Opaque here and never parsed; the\"", "            \" control store holds the namespace policy and the binding cache that \"", "            \"resolve it.\"", "        ),", "    )", "", "    external_operation_key: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"The source's own identifier for the operation, paired with the \"", "            \"namespace above and unique only within it. Part of the pre-scope \"", "            \"identity, so a redelivery naming the same reference returns the \"", "            \"original receipt rather than opening a second pending unit. Never \"", "            \"parsed and never used to derive an operation id locally; resolution is\"", "            \" the platform's to perform.\"", "        ),", "    )", "", "    scope_key: Mapped[str | None] = mapped_column(", "        Text(),", "        Computed(", "            \"CASE WHEN scope_kind IS NULL THEN NULL WHEN scope_kind = 'OPERATION' THEN 'client\\\\:' || client_id::text || '\\\\:operation\\\\:' || operation_id::text ELSE 'client\\\\:' || client_id::text || '\\\\:standing' END\",", "            persisted=True,", "        ),", "        nullable=True,", "        comment=(", "            \"The identity of one concrete data scope. Physically a stored generated\"", "            \" column, computed by the database as CASE WHEN scope_kind IS NULL THEN\"", "            \" NULL WHEN scope_kind = 'OPERATION' THEN 'client:' || client_id::text \"", "            \"|| ':operation:' || operation_id::text ELSE 'client:' || \"", "            \"client_id::text || ':standing' END, and never written directly. Two \"", "            \"resolved forms only, matching the canonical grammar the Accelerate \"", "            \"store shares; ledger intake never carries platform scope. Never parsed\"", "            \" by any reader: retrieval, policy and metering use the typed columns, \"", "            \"so the format stays changeable. Null exactly while a delivery naming \"", "            \"an external operation reference awaits resolution and on a terminal \"", "            \"outcome that never resolved; resolution fills it once and an \"", "            \"immutability trigger rejects any later rewrite or clearing. The null \"", "            \"case is safe because every downstream table declares scope_key NOT \"", "            \"NULL and every child edge is a composite foreign key onto (id, \"", "            \"scope_key): a child must supply a non-null value, no unscoped parent \"", "            \"carries one, and the reference is refused by the database rather than \"", "            \"by application code. Carried into every same-scope foreign key that \"", "            \"names a delivery, and into the natural-key index, so the same \"", "            \"unit_natural_key from the same source deduplicates within a scope \"", "            \"rather than within a client.\"", "        ),", "    )", "", "    source_dataset_binding_id: Mapped[UUIDType] = mapped_column(", "        UUID(as_uuid=True),", "        nullable=False,", "        comment=(", "            \"The dataset binding that resolved this delivery's dataset at \"", "            \"admission. Deliberately FK-less, like source_policy_id: bindings are \"", "            \"versioned in the ingest_control database and no transaction spans the \"", "            \"two.\"", "        ),", "    )", "", "    source_dataset_binding_version: Mapped[int] = mapped_column(", "        Integer(),", "        nullable=False,", "        comment=(", "            \"The binding version in force at admission. Recorded alongside the \"", "            \"binding identity so a delivery names not just which dataset it \"", "            \"belonged to but which resolution said so, and a later rebinding cannot\"", "            \" change what an admitted delivery meant.\"", "        ),", "    )", "", "    dataset_id: Mapped[UUIDType] = mapped_column(", "        UUID(as_uuid=True),", "        nullable=False,", "        comment=(", "            \"The one dataset this delivery belongs to, resolved from the binding at\"", "            \" admission and copied unchanged onto every lineage and claim beneath \"", "            \"it. A payload spanning datasets is split into separate delivery units \"", "            \"rather than carrying two identities here. Deliberately FK-less in this\"", "            \" direction: the dataset catalog is in the Accelerate database, and the\"", "            \" intake path never calls it.\"", "        ),", "    )", "", "    dataset_catalog_version: Mapped[int] = mapped_column(", "        Integer(),", "        nullable=False,", "        comment=(", "            \"The dataset catalog version the binding was activated against, copied \"", "            \"through from the binding. Lets a delivery be read against the dataset \"", "            \"semantics in force when it was admitted; a later catalog version does \"", "            \"not retroactively change what it meant.\"", "        ),", "    )", "", "    intake_principal_id: Mapped[UUIDType] = mapped_column(", "        UUID(as_uuid=True),", "        nullable=False,", "        comment=(", "            \"The ingestion machine principal that authenticated this delivery. With\"", "            \" intake_authorization_version, resolves the exact authority tuple in \"", "            \"force at admission. Deliberately FK-less: principals and their \"", "            \"authorization history are held in the ingest_control database, which \"", "            \"enforces the composite key of principal and authorization version, and\"", "            \" no transaction spans the two databases.\"", "        ),", "    )", "", "    intake_authorization_version: Mapped[int] = mapped_column(", "        Integer(),", "        nullable=False,", "        comment=(", "            \"The principal's authorization registration version in force when this \"", "            \"unit was admitted. Stamped from the resolved principal, never from \"", "            \"payload. Replay and reprocessing read this recorded version rather \"", "            \"than the current one, so a later authorization change cannot \"", "            \"retroactively widen or narrow what this delivery was permitted to do. \"", "            \"Credential rotation does not change it; an authorization change does \"", "            \"not change the principal.\"", "        ),", "    )", "", "    unit_natural_key: Mapped[str] = mapped_column(", "        Text(),", "        nullable=False,", "        comment=(", "            \"From delivery config, constructed according to unit_natural_key_kind. \"", "            \"For a source-versioned delivery this carries the source record id \"", "            \"together with the native version; for a sender-deduplicated one it is \"", "            \"the sender's own key verbatim; for a minted one it is a \"", "            \"platform-assigned identity that never collides. Never derived from \"", "            \"content, because a change sequence returning to an earlier content \"", "            \"state would collapse distinct deliveries.\"", "        ),", "    )", "", "    ingest_batch_id: Mapped[UUIDType | None] = mapped_column(", "        UUID(as_uuid=True),", "        nullable=True,", "        comment=(", "            \"Groups a run (\u00a76.4). No FK \u2014 cross-database. Relationship to Scoring \"", "            \"common.batches is unresolved; see the batch-completeness open item.\"", "        ),", "    )", "", "    ingestion_method: Mapped[str] = mapped_column(", "        INGESTION_METHODS,", "        nullable=False,", "        comment=\"Denormalized from the source system so the sweep needn't join.\",", "    )", "", "    state: Mapped[str] = mapped_column(", "        DELIVERY_UNIT_STATES,", "        nullable=False,", "        comment=(\"\u00a74.1 state machine. Terminal: QUARANTINED, EXPIRED, ABSORBED_DUPLICATE.\"),", "    )", "", "    declared_lifecycle_op: Mapped[str] = mapped_column(", "        LIFECYCLE_OPS,", "        nullable=False,", "        comment=(", "            \"The lifecycle operation this delivery declares, validated at intake \"", "            \"against the operations its source system is permitted to send. \"", "            \"Declared, never inferred: absence of a record from a delivery is not a\"", "            \" delete. A declared operation outside the permitted set quarantines \"", "            \"the unit with LIFECYCLE_OP_NOT_PERMITTED.\"", "        ),", "    )", "", "    quarantine_reason_code: Mapped[str | None] = mapped_column(", "        QUARANTINE_REASON_CODES,", "        nullable=True,", "        comment=(", "            \"Why a delivery unit was quarantined or expired. Recorded \u2014 never a silent \"", "            \"drop. Two of the values are bound to one arrival mode each and to a row \"", "            \"that never landed, because they name a failure only that mode can have and \"", "            \"only before anything landed: INTENT_EXPIRED belongs to an UPLOAD_INTENT \"", "            \"whose window closed with nothing landed, and LANDING_ABANDONED belongs to \"", "            \"an unlanded REQUEST_BYTES row, which has no window to close and is \"", "            \"terminated by reconciliation instead. Once an object lands the row \"", "            \"advances out of the window, so neither reason can describe it and a later \"", "            \"termination of a landed row carries a different code. \"", "            \"ck_delivery_units_unlanded_terminal_reason enforces both pairings, so \"", "            \"neither reason can be recorded against a mode that cannot produce it or \"", "            \"against a row that already landed; ck_delivery_units_quarantine_reason \"", "            \"separately governs when a reason must be present at all.\"", "        ),", "    )", "", "    quarantine_reason_detail: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"Free-text detail accompanying the typed quarantine reason code, for \"", "            \"operator reading. Never parsed and never a substitute for the code: \"", "            \"routing, metrics and policy read the enum, and this explains the \"", "            \"particular case to a person.\"", "        ),", "    )", "", "    duplicate_of_delivery_unit_id: Mapped[UUIDType | None] = mapped_column(", "        UUID(as_uuid=True),", "        nullable=True,", "        comment=(", "            \"The already-resolved delivery this unit was absorbed into. An absorbed \"", "            \"duplicate is the still-unscoped loser of a bind from \"", "            \"PENDING_OPERATION_RESOLUTION: it never receives scope, stays childless, \"", "            \"returns the original's receipt, and reverses its surplus reservation \"", "            \"append-only. The target must already carry resolved scope, must share \"", "            \"this unit's client, source system and normalized unit transport identity, \"", "            \"and must not itself be an absorbed duplicate, so absorption can never \"", "            \"cross clients and duplicates never chain. The target's scope may have \"", "            \"been resolved at receipt or filled later by the resolver; scope_bound_at \"", "            \"is null in the first case and is therefore not what identifies a scoped \"", "            \"target. trg_delivery_units_absorption_origin enforces that the loser \"", "            \"arrives from PENDING_OPERATION_RESOLUTION and from no other state. The \"", "            \"composite foreign key on this column and client_id refuses a cross-client \"", "            \"absorption outright; trg_delivery_units_duplicate_scope enforces the \"", "            \"remaining three conditions.\"", "        ),", "    )", "", "    transport_dedup_hint: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"Offset / request id / object key / LSN. A hint, never the identity. \"", "            \"Distinct from original_locator: this is the transport coordinate the \"", "            \"adapter observed, not the address the submitter supplied.\"", "        ),", "    )", "", "    original_locator: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"The submitter's own address for this unit \u2014 source URI, filename, or \"", "            \"export coordinate. Recorded for audit and operator provenance; never \"", "            \"parsed, and never authoritative over the trusted envelope.\"", "        ),", "    )", "", "    trace_id: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"Trace identifier correlating the intake request with downstream \"", "            \"stages. Diagnostic only, never an identity.\"", "        ),", "    )", "", "    quarantine_bucket: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"Bucket holding the quarantined object for this unit. Part of the \"", "            \"immutable quarantine reference, paired with quarantine_key and \"", "            \"completed by the object version id and content hash once the object \"", "            \"has landed.\"", "        ),", "    )", "", "    quarantine_key: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"Derived from Id \u2014 a re-landed unit lands on its own key, never a sibling orphan.\"", "        ),", "    )", "", "    quarantine_object_version_id: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"The object version landed at the quarantine key. The key is assigned \"", "            \"at intent time from the resolved principal scope, so a later write to \"", "            \"the same key creates a further version; scan, hash verification, and \"", "            \"promotion all read the version recorded here. Null until the object \"", "            \"lands.\"", "        ),", "    )", "", "    quarantine_content_hash: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"Content hash of the landed quarantine object. With quarantine_bucket, \"", "            \"quarantine_key, quarantine_object_version_id and quarantine_size_bytes\"", "            \" this is the immutable address of the bytes as received, in the same \"", "            \"five-part form as the evidence_* reference. Null until the object \"", "            \"lands.\"", "        ),", "    )", "", "    quarantine_size_bytes: Mapped[int | None] = mapped_column(", "        BigInteger(),", "        nullable=True,", "        comment=(", "            \"Size in bytes of the quarantined object, observed at landing rather \"", "            \"than declared; declared_size_bytes carries the submitter's claim and a\"", "            \" mismatch between the two yields no accepted receipt. The fifth part \"", "            \"of the immutable quarantine reference, which is complete only as \"", "            \"bucket, key, object version id, content hash and size together.\"", "        ),", "    )", "", "    evidence_bucket: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"Bucket holding the promoted evidence object for this unit. Null until \"", "            \"promotion, and null permanently where the payload disposition means no\"", "            \" bytes are held here. Part of the immutable evidence reference, which \"", "            \"is never overwritten once captured.\"", "        ),", "    )", "", "    evidence_key: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"Deterministic key of the promoted evidence object. Deterministic so a \"", "            \"retry resolves the same address: an existing object with a matching \"", "            \"hash is adopted idempotently, and a mismatched hash is a terminal \"", "            \"failure rather than an overwrite.\"", "        ),", "    )", "", "    evidence_object_version_id: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"Object store version id captured at promotion, pinning the exact \"", "            \"version this receipt refers to. Without it a later write under the \"", "            \"same key would silently change what the receipt points at, which is \"", "            \"the fault the immutable reference exists to prevent.\"", "        ),", "    )", "", "    evidence_content_hash: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"The five evidence_* columns are the immutable evidence reference \u2014 \"", "            \"bucket, key, object version-id, content hash, and size in bytes \u2014 \"", "            \"bound all-or-nothing by ck_delivery_units_evidence_reference. A bare \"", "            'URI resolves to \"latest\" in a versioned bucket and is not an immutable'", "            \" evidence address.\"", "        ),", "    )", "", "    evidence_size_bytes: Mapped[int | None] = mapped_column(", "        BigInteger(),", "        nullable=True,", "        comment=(", "            \"Size in bytes of the promoted evidence object. The fifth part of the \"", "            \"immutable evidence reference, recorded separately from the quarantine \"", "            \"size so each reference stands alone and a reader reconstructing one \"", "            \"does not have to know that a neighbouring pointer lends it a column. \"", "            \"Equal to the quarantine size under a byte-for-byte promotion; no \"", "            \"constraint asserts that, because a promotion that legitimately \"", "            \"re-wraps would be refused by one.\"", "        ),", "    )", "", "    content_type: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"Content type of the landed object as determined by inspection, which \"", "            \"is what parsing and capability resolution use. declared_content_type \"", "            \"carries what the submitter asserted, and the two are kept apart so a \"", "            \"wrong declaration is visible rather than authoritative.\"", "        ),", "    )", "", "    declared_content_type: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"Content type declared by the submitter before upload, validated \"", "            \"against the landed object. Null where no prior declaration exists.\"", "        ),", "    )", "", "    declared_content_hash: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"SHA-256 declared by the submitter before upload and signed into the \"", "            \"presigned request as a literal value rather than as an algorithm name,\"", "            \" so the stored object carries a checksum comparable without re-reading\"", "            \" the bytes. Null where no prior declaration exists.\"", "        ),", "    )", "", "    declared_size_bytes: Mapped[int | None] = mapped_column(", "        BigInteger(),", "        nullable=True,", "        comment=(", "            \"Size declared by the submitter before upload, validated against the \"", "            \"landed object. A mismatch produces no accepted receipt. Null where \"", "            \"bytes transit the request handler inline and no prior declaration \"", "            \"exists.\"", "        ),", "    )", "", "    manifest_representation: Mapped[str | None] = mapped_column(", "        MANIFEST_REPRESENTATIONS,", "        nullable=True,", "        comment=(", "            \"EXPLICIT where fan-out is enumerable; WATERMARK at high cardinality. \"", "            \"NULL until post-scan normalization decides the plan \u2014 the unit row \"", "            \"exists from RECEIVED, before fan-out cardinality is known.\"", "        ),", "    )", "", "    manifest_watermark_ordinal: Mapped[int | None] = mapped_column(", "        Integer(),", "        nullable=True,", "        comment=(\"Contiguous-progress watermark. Required iff representation is WATERMARK.\"),", "    )", "", "    manifest_planned_count: Mapped[int | None] = mapped_column(", "        Integer(),", "        nullable=True,", "        comment=(", "            \"Number of manifest entries planned for this unit. Present where the \"", "            \"manifest representation is explicit and the full set is known at \"", "            \"planning time; a watermark representation tracks progress by ordinal \"", "            \"instead and leaves this null. Completion is a durable manifest \"", "            \"predicate, so this is an accounting aid and never the completion test \"", "            \"itself.\"", "        ),", "    )", "", "    unit_natural_key_kind: Mapped[str] = mapped_column(", "        UNIT_NATURAL_KEY_KINDS,", "        nullable=False,", "        comment=(", "            \"How unit_natural_key was constructed for this delivery, and therefore \"", "            \"what a collision on it means. SOURCE_VERSIONED and SENDER_DEDUP_KEY \"", "            \"keys collide on redelivery of the same version; a MINTED key is \"", "            \"assigned by the platform and never collides, so deliveries from those \"", "            \"sources are deduplicated after normalization against the claim on the \"", "            \"record lineage rather than at admission. Write-once. The \"", "            \"duplicate-absorption check matches a loser against its original on this \"", "            \"column together with unit_natural_key, and it runs only at the moment of \"", "            \"absorption; a later change would silently reinterpret what the original's \"", "            \"key means without re-testing the match.\"", "        ),", "    )", "", "    payload_disposition: Mapped[str] = mapped_column(", "        PAYLOAD_DISPOSITIONS,", "        nullable=False,", "        comment=(", "            \"The effective disposition of this delivery's payload, resolved at \"", "            \"intake from the source system's default and the delivery's own \"", "            \"declaration. Determines which evidence and reference columns this row \"", "            \"may carry, and is paired with payload_arrival_mode: a durable or \"", "            \"transient disposition requires bytes to arrive by one of the two \"", "            \"byte-carrying modes, and an external reference or a receipt requires \"", "            \"that none arrive at all. Validated against the dispositions the source\"", "            \" system is permitted to send; one outside that set quarantines the \"", "            \"unit with PAYLOAD_DISPOSITION_NOT_PERMITTED. Fixed at admission from \"", "            \"the delivery plus the pinned local policy and authorization, and \"", "            \"write-once: binding an operation later resolves scope and nothing \"", "            \"else, so a delivery's disposition cannot change when its scope does.\"", "        ),", "    )", "", "    payload_arrival_mode: Mapped[str] = mapped_column(", "        PAYLOAD_ARRIVAL_MODES,", "        nullable=False,", "        comment=(", "            \"How this delivery's payload reaches the platform: inline in the \"", "            \"request, through an issued upload window, or not at all. Fixed at \"", "            \"admission from the delivery plus the pinned local policy and \"", "            \"authorization, and write-once \u2014 it cannot change when the operation is\"", "            \" later bound, because binding resolves scope and nothing else. \"", "            \"Determines which of the intent, quarantine and evidence columns may be\"", "            \" populated, and which terminal path an incomplete landing takes: an \"", "            \"unused upload window expires, an abandoned inline landing is \"", "            \"terminated by reconciliation, and a delivery that was never going to \"", "            \"carry bytes has neither.\"", "        ),", "    )", "", "    external_reference_uri: Mapped[str | None] = mapped_column(", "        Text(),", "        nullable=True,", "        comment=(", "            \"The reference accepted in place of the bytes. Set only where \"", "            \"payload_disposition is EXTERNAL_REFERENCE, in which case no Polaris \"", "            \"evidence object exists for this delivery. Distinct from \"", "            \"original_locator, which is the submitter's own address for a delivery \"", "            \"whose bytes were received; this is the accepted payload itself. \"", "            \"Whether it may later be fetched is governed by the source system's \"", "            \"dereference policy, and any fetch is recorded separately from this \"", "            \"receipt.\"", "        ),", "    )", "", "    intake_credential_id: Mapped[UUIDType] = mapped_column(", "        UUID(as_uuid=True),", "        nullable=False,", "        comment=(", "            \"The credential presented by the intake principal for this delivery. \"", "            \"Recorded because rotation replaces the credential without changing the\"", "            \" principal or its authorization version, so the credential in force is\"", "            \" not recoverable from the other two. Deliberately FK-less: credentials\"", "            \" are held in the ingest_control database and no transaction spans the \"", "            \"two.\"", "        ),", "    )", "", "    intake_authorization_snapshot_id: Mapped[UUIDType] = mapped_column(", "        UUID(as_uuid=True),", "        nullable=False,", "        comment=(", "            \"Globally unique identifier of the authorization snapshot in force when\"", "            \" this unit was admitted. Deliberately FK-less: the snapshot is held in\"", "            \" the ingest_control database and no transaction spans the two. The \"", "            \"intake service validates the snapshot before this receipt is written; \"", "            \"there is no referential guarantee after the fact.\"", "        ),", "    )", "", "    intake_authorization_snapshot_digest: Mapped[str] = mapped_column(", "        Text(),", "        nullable=False,", "        comment=(", "            \"Immutable digest over the authorization snapshot named by \"", "            \"intake_authorization_snapshot_id. Recorded so a snapshot altered after\"", "            \" admission is detectable from the receipt alone, without reading the \"", "            \"control database.\"", "        ),", "    )", "", "    intake_reservation_id: Mapped[UUIDType] = mapped_column(", "        UUID(as_uuid=True),", "        nullable=False,", "        comment=(", "            \"The quota reservation this delivery was admitted against, in the \"", "            \"control store. Present on every unit including a pending one, because \"", "            \"a pending unit has already consumed capacity and its reservation must \"", "            \"be reversible by id when resolution refuses, expires, or absorbs it as\"", "            \" a duplicate. Deliberately FK-less: the reservation lives in a \"", "            \"different database and no cross-database transaction exists.\"", "        ),", "    )", "", "    resolved_latency_class: Mapped[str] = mapped_column(", "        LATENCY_CLASSES,", "        nullable=False,", "        comment=(", "            \"The scheduling urgency resolved at admission from the pinned principal\"", "            \" and source declarations. Stamped on the receipt so a replay reaches \"", "            \"the same decision the original delivery did. Records the unit grain \"", "            \"only: a later escalation or downgrade is a separate effective class on\"", "            \" the manifest or work row, and never an edit to this value, which \"", "            \"trg_delivery_units_set_once enforces as write-once.\"", "        ),", "    )", "", "    ordering_mode: Mapped[str] = mapped_column(", "        ORDERING_MODE_TYPES,", "        nullable=False,", "        comment=(", "            \"How this source orders versions of a record, materialized from the \"", "            \"pinned policy at intake. Held on the delivery rather than read from \"", "            \"the source system, because reprocessing must reach the same ordering \"", "            \"decision it reached originally even where a later policy version \"", "            \"changed the mode and even where the pinned version has been archived.\"", "        ),", "    )", "", "    version_order_encoding: Mapped[str] = mapped_column(", "        VERSION_ORDER_ENCODINGS,", "        nullable=False,", "        comment=(", "            \"The encoding used to construct version_order_key for records reached \"", "            \"through this delivery, materialized from the pinned policy. Claims \"", "            \"carry it again at their own grain; both are pinned because a claim can\"", "            \" be written long after the delivery that produced it.\"", "        ),", "    )", "", "    version_order_encoding_version: Mapped[int] = mapped_column(", "        Integer(),", "        nullable=False,", "        comment=(", "            \"Which revision of that encoding applied. An encoding revision changes \"", "            \"how keys sort, so a delivery reprocessed under a later revision would \"", "            \"order against keys it cannot compare with.\"", "        ),", "    )", "", "    delete_semantics: Mapped[str] = mapped_column(", "        DELETE_SEMANTIC_MODES,", "        nullable=False,", "        comment=(", "            \"How a delete or tombstone from this source is to be interpreted, \"", "            \"materialized from the pinned policy. Determines whether a delete \"", "            \"supersedes a record, removes it, or is advisory, and reprocessing must\"", "            \" reach the same conclusion the original run did.\"", "        ),", "    )", "", "    born_superseded_posture: Mapped[str] = mapped_column(", "        BORN_SUPERSEDED_POSTURES,", "        nullable=False,", "        server_default=text(\"'SKIP'\"),", "        comment=(", "            \"What to do with a version that arrives already superseded, \"", "            \"materialized from the pinned policy. Governs whether such a version is\"", "            \" skipped or recorded, which changes what claims exist and therefore \"", "            \"what a replay produces.\"", "        ),", "    )", "", "    downstream_route: Mapped[str] = mapped_column(", "        DOWNSTREAM_ROUTES,", "        nullable=False,", "        comment=(", "            \"Where content from this delivery is routed, materialized from the \"", "            \"pinned policy. Held here because the route determines which downstream\"", "            \" surfaces may ever see this delivery and a policy change must not \"", "            \"retroactively redirect deliveries already accepted.\"", "        ),", "    )", "", "    effective_security_label: Mapped[str] = mapped_column(", "        Text(),", "        nullable=False,", "        comment=(", "            \"The security label in force for this delivery, resolved at intake from\"", "            \" the pinned policy default and anything the delivery declared. The \"", "            \"effective value rather than the source default, because a delivery may\"", "            \" carry a more restrictive label than its source's baseline and the \"", "            \"more restrictive value governs.\"", "        ),", "    )", "", "    source_policy_id: Mapped[UUIDType] = mapped_column(", "        UUID(as_uuid=True),", "        nullable=False,", "        comment=(", "            \"The immutable source policy that governed this delivery. Deliberately \"", "            \"FK-less: source policies are versioned in the ingest_control database \"", "            \"and no transaction spans the two.\"", "        ),", "    )", "", "    source_policy_version: Mapped[int] = mapped_column(", "        Integer(),", "        nullable=False,", "        comment=(", "            \"Which version of that policy applied. Pinned rather than resolved at \"", "            \"read time, because the policy is versioned and a later version must \"", "            \"not reinterpret what this delivery was permitted to do.\"", "        ),", "    )", "", "    source_policy_digest: Mapped[str] = mapped_column(", "        Text(),", "        nullable=False,", "        comment=(", "            \"Immutable digest over the pinned policy version. Recorded so a policy \"", "            \"altered after the fact is detectable from this row alone, without \"", "            \"reading the control database.\"", "        ),", "    )", "", "    received_at: Mapped[datetime] = mapped_column(", "        DateTime(timezone=True),", "        nullable=False,", "        comment=\"Clock start for source-to-persist latency.\",", "    )", "", "    intent_expires_at: Mapped[datetime | None] = mapped_column(", "        DateTime(timezone=True),", "        nullable=True,", "        comment=(", "            \"When a delivery intent's upload window closes. Non-null exactly when \"", "            \"the arrival mode is UPLOAD_INTENT, and null for every other mode. An \"", "            \"intent reaching this time with no landed object becomes EXPIRED with \"", "            \"INTENT_EXPIRED, and its accounting row persists with no evidence \"", "            \"address. A request-bytes delivery has no window to close, so an \"", "            \"incomplete landing there is found by reconciliation and terminated as \"", "            \"LANDING_ABANDONED instead.\"", "        ),", "    )", "", "    landed_at: Mapped[datetime | None] = mapped_column(", "        DateTime(timezone=True),", "        nullable=True,", "        comment=(", "            \"When the object arrived at its recorded address. Null on a unit whose \"", "            \"intent expired with nothing landed, and null on every delivery that \"", "            \"carries no Polaris bytes. Write-once once set: the \"", "            \"quarantine-reference constraint reads this column to decide whether \"", "            \"the quarantine address is mandatory, so a unit holding an object keeps\"", "            \" the timestamp through every later state including its terminal one.\"", "        ),", "    )", "", "    scope_bound_at: Mapped[datetime | None] = mapped_column(", "        DateTime(timezone=True),", "        nullable=True,", "        comment=(", "            \"When resolution filled this unit's scope. Null on a unit that was \"", "            \"never pending and on one that terminated unresolved. Marks the single \"", "            \"null-to-valid scope transition the design permits, which an \"", "            \"immutability trigger enforces as one-time: scope may never afterwards \"", "            \"be rewritten or cleared.\"", "        ),", "    )", "", "    accepted_at: Mapped[datetime | None] = mapped_column(", "        DateTime(timezone=True),", "        nullable=True,", "        comment=\"Promotion to evidence lake.\",", "    )", "", "    ready_at: Mapped[datetime | None] = mapped_column(", "        DateTime(timezone=True),", "        nullable=True,", "        comment=\"Normalization plan durable; no work published yet.\",", "    )", "", "    published_at: Mapped[datetime | None] = mapped_column(", "        DateTime(timezone=True),", "        nullable=True,", "        comment=(", "            \"When work publication for this unit was committed to the queue or \"", "            \"outbox. Says nothing about the system of record: a published unit may \"", "            \"have no canonical row in Accelerate, and canonical persistence is \"", "            \"recorded per claim rather than here.\"", "        ),", "    )", "", "    extracted_at: Mapped[datetime | None] = mapped_column(", "        DateTime(timezone=True),", "        nullable=True,", "        comment=(", "            \"When every manifest entry for this unit reached a terminal outcome and\"", "            \" no generative stage could still append. The durable manifest \"", "            \"predicate, stamped once it holds.\"", "        ),", "    )", "", "    persisted_at: Mapped[datetime | None] = mapped_column(", "        DateTime(timezone=True),", "        nullable=True,", "        comment=\"Set when the SoR writes commit.\",", "    )", "", "    terminal_at: Mapped[datetime | None] = mapped_column(", "        DateTime(timezone=True),", "        nullable=True,", "        comment=(", "            \"When this unit entered a terminal state, whether quarantined, expired,\"", "            \" or absorbed into an earlier delivery. Null on a unit still in \"", "            \"progress, and never cleared, so the accounting row explains what \"", "            \"happened after the bytes themselves are gone. Required on an absorbed \"", "            \"duplicate, where it is the only clock the row carries.\"", "        ),", "    )", "", "    created_at: Mapped[datetime] = mapped_column(", "        DateTime(timezone=True),", "        nullable=False,", "        server_default=text(\"now()\"),", "    )", "", "    updated_at: Mapped[datetime | None] = mapped_column(", "        DateTime(timezone=True),", "        nullable=True,", "        comment=(", "            \"When this row last changed, which is any fenced state transition or \"", "            \"the one-time scope binding. Null while the unit is untouched since \"", "            \"insert.\"", "        ),", "    )"], "blocks": [{"start": 1, "end": 41, "label": "Imports and module setup"}, {"start": 42, "end": 1073, "label": "class DeliveryUnit"}], "lineCount": 1073, "sha256": "7cf327c9f68e3401023c39dc9b7e5266affe29f8a4915120af157faf4de88cce", "endsWithNewline": true});
